import axios from "axios";

const API_BASE = "http://localhost:5000/api";

export const verifyVoter = (voter_hash) =>
  axios.post(`${API_BASE}/auth/verify-voter`, { voter_hash });

export const castVote = (voter_hash, candidate_id, ballot) =>
  axios.post(`${API_BASE}/vote/cast`, { voter_hash, candidate_id, ballot });

export const getCandidates = () =>
  axios.get(`${API_BASE}/candidates`);

export const loginAdmin = (username, password) =>
  axios.post(`${API_BASE}/auth/login`, { username, password });

export const getResults = () =>
  axios.get(`${API_BASE}/admin/results`);
